// ============ KOOK SETTINGS ============  (edit these, nothing else)
return [{ json: {
  // --- you
  CUSTOMER_NAME: 'YOUR_NAME',
  MY_PHONE: 'YOUR_MOBILE',          // the pre-wake text + (TEST_MODE) every call and sick text
  TWILIO_FROM: 'YOUR_TWILIO_NUMBER',
  TELEGRAM_CHAT_ID: 'YOUR_TELEGRAM_CHAT_ID',
  // --- the cover story
  BOSS_PHONE: 'YOUR_MOBILE',        // who gets "feeling a bit off this morning"
  CALENDAR_ID: 'YOUR_GOOGLE_CALENDAR_ID',   // Google Calendar id whose meetings move to tomorrow
  // --- the bakery
  BAKERY_NAME: 'the local bakery',
  BAKERY_PHONE: 'YOUR_MOBILE',      // real bakery number goes here when TEST_MODE is off
  ORDER: 'a pie and a custard tart',
  PICKUP_IN_MIN: 15,
  VOICE_PROVIDER: 'bland',           // 'elevenlabs' once the agent + Twilio number are connected
  ELEVENLABS_AGENT_ID: '',
  ELEVENLABS_PHONE_NUMBER_ID: '',
  BLAND_VOICE: 'mason',
  // --- the call on the surf
  MIN_SURF_FT: 3,        // Surfline's scale
  MAX_WIND_KT: 12,       // light winds only
  EARLIEST_HOUR: 5,
  FIRST_LIGHT_HOUR: 6,   // don't fire before the cams can see (Perth sunrise ~5:10am Dec, ~7:15am Jun)
  BEFORE_HOUR: 10,       // has to be on before 10am
  SESSION_MIN: 90,
  TRAVEL_MIN: 20,
  // --- the crowd count
  VISION_MODEL: 'claude-sonnet-5',   // Haiku undercounts: a surfer on a cam is a few pixels
  CROWD_PROMPT: "This is a zoomed strip of a live surf webcam, showing the lineup at a beach break. Surfers are tiny dark specks or short dark lines sitting or lying on boards, around and just beyond the whitewater. Work left to right across the whole strip. First list every surfer you can see with a rough horizontal position as a percentage of the width, then give the total. Do not count birds, buoys, foam or people on the sand. Finish with one line of JSON only: {\"surfers\": <int>, \"visibility\": \"good|poor|dark\"}",
  CAM_W: 1280, CAM_H: 720,           // Surfline cam stills are 1280x720
  SEED_CROWD: null,      // filming: e.g. { 'Trigg Point': 11 } replaces a dark/unreadable count
  // --- safety
  TEST_MODE: true,       // calls + sick text go to MY_PHONE, drive-home wait is 1 minute
  FORCE_FIRE: false,     // true = run the whole cascade even when the surf is rubbish
  // --- breaks. Surfline spotIds are public. Only Trigg has cams; the others are forecast only.
  // crop = the strip of water the lineup sits in, as fractions of the frame height, zoomed before counting.
  // The whole frame counted 3 when 8 were out. Tune top/bottom per cam; null counts the whole frame.
  SPOTS: [
    { name: 'Trigg', spotId: '584204204e65fad6a7709268', lat: -31.8784, lon: 115.7513, shoreFacing: 270,
      cams: [
        { break: 'Trigg Point', still: 'https://camstills.cdn-surfline.com/ap-southeast-2/au-triggpoint/latest_full.jpg', crop: { top: 0.52, bottom: 0.70, zoom: 2 } },
        { break: 'North Trigg', still: 'https://camstills.cdn-surfline.com/ap-southeast-2/au-northtriggbeach/latest_full.jpg', crop: null },
        { break: 'Trigg Beach', still: 'https://camstills.cdn-surfline.com/ap-southeast-2/au-triggbeach/latest_full.jpg', crop: null },
        { break: 'South Trigg', still: 'https://camstills.cdn-surfline.com/ap-southeast-2/au-sthtriggbeach/latest_full.jpg', crop: null },
      ] },
    { name: 'Scarborough', spotId: '5842041f4e65fad6a7708c1e', lat: -31.8914, lon: 115.7539, shoreFacing: 270, cams: [] },
    { name: 'Cottesloe', spotId: '5842041f4e65fad6a7708c1f', lat: -32.0073, lon: 115.7513, shoreFacing: 270, cams: [] },
  ],
} }];

const S = $('Kook settings').first().json;
const spots = $('Split spots').all().map(i => i.json);
const TZ = 'Australia/Perth';
const now = new Date();
const hourOf = d => Number(new Intl.DateTimeFormat('en-AU', { timeZone: TZ, hour: '2-digit', hourCycle: 'h23' }).format(d));
const dayOf = d => new Intl.DateTimeFormat('en-CA', { timeZone: TZ }).format(d);
const today = dayOf(now);
const asJson = v => {
  if (v == null) return null;
  if (typeof v === 'object' && v.data && (v.data.wave || v.data.wind)) return v;
  let t = typeof v === 'string' ? v : (v.data ?? v.body ?? JSON.stringify(v));
  if (typeof t !== 'string') return null;
  const s = t.indexOf('{'), e = t.lastIndexOf('}');
  try { return s < 0 ? null : JSON.parse(t.slice(s, e + 1)); } catch (err) { return null; }
};
const windType = (from, facing) => {
  const offshoreFrom = (facing + 180) % 360;
  const d = Math.abs(((from - offshoreFrom) % 360 + 540) % 360 - 180);
  return d <= 45 ? 'Offshore' : d <= 100 ? 'Cross-shore' : 'Onshore';
};
const score = r => r.surfFt * 2 - r.windKt * 0.3 + (r.windType === 'Offshore' ? 3 : 0);
const out = spots.map((sp, i) => {
  const w = asJson($('Surfline swell').all()[i]?.json), wi = asJson($('Surfline wind').all()[i]?.json);
  const om = $('Open-Meteo swell (backup)').all()[i]?.json, ow = $('Open-Meteo wind (backup)').all()[i]?.json;
  let rows = [], source = 'Surfline';
  if (w?.data?.wave?.length && wi?.data?.wind?.length) {
    const byTs = {}; wi.data.wind.forEach(x => byTs[x.timestamp] = x);
    rows = w.data.wave.map(x => ({ t: new Date(x.timestamp * 1000), surfFt: x.surf.max,
      windKt: Math.round(byTs[x.timestamp]?.speed ?? 99), windType: byTs[x.timestamp]?.directionType || 'Onshore' }));
  } else if (om?.hourly && ow?.hourly) {
    source = 'Open-Meteo';   // metres of wave height, roughly converted to Surfline's scale
    rows = om.hourly.time.map((ts, k) => ({ t: new Date(ts + ':00+08:00'),
      surfFt: Math.round(om.hourly.wave_height[k] * 3.28 * 0.6 * 10) / 10,
      windKt: Math.round(ow.hourly.wind_speed_10m[k]), windType: windType(ow.hourly.wind_direction_10m[k], sp.shoreFacing) }));
  }
  const morning = rows.filter(r => dayOf(r.t) === today && hourOf(r.t) >= S.EARLIEST_HOUR && hourOf(r.t) < S.BEFORE_HOUR
                                   && r.t.getTime() >= now.getTime() - 3600e3);
  const good = morning.filter(r => r.surfFt >= S.MIN_SURF_FT && r.windKt <= S.MAX_WIND_KT && r.windType !== 'Onshore');
  // Past the morning window (a forced afternoon run for filming), use the NEAREST coming hour. Taking the best
  // score of the whole day picked 11pm on 13 Sep and texted "Best at 11:00pm".
  const upcoming = rows.filter(r => r.t.getTime() >= now.getTime() - 3600e3).sort((a, b) => a.t - b.t);
  const best = (good.length ? good : morning).sort((a, b) => score(b) - score(a))[0] || upcoming[0] || rows.sort((a, b) => score(b) - score(a))[0];
  return { spot: sp.name, source, on: good.length > 0, cams: sp.cams || [],
           best: best ? { at: best.t.toISOString(), surfFt: best.surfFt, windKt: best.windKt, windType: best.windType, score: Math.round(score(best) * 10) / 10 } : null };
});
out.sort((a, b) => (b.on - a.on) || ((b.best?.score ?? -99) - (a.best?.score ?? -99)));
const sd = $getWorkflowStaticData('global');
let firing = out.some(s => s.on) || S.FORCE_FIRE;
if (firing && !S.FORCE_FIRE && hourOf(now) < (S.FIRST_LIGHT_HOUR ?? 0)) firing = false;   // cams can't see yet; the first run after light fires
if (firing && sd.firedOn === today && !S.FORCE_FIRE && !S.TEST_MODE) firing = false;   // once a day in production
if (firing) sd.firedOn = today;
return [{ json: { firing, forced: S.FORCE_FIRE && !out.some(s => s.on), spots: out } }];

const S = $('Kook settings').first().json;
const m = $('Score the morning').first().json;
const items = [];
for (const s of m.spots) for (const c of s.cams) {
  const cr = c.crop || { top: 0, bottom: 1, zoom: 1 };   // no crop = count the whole frame
  const y = Math.round(S.CAM_H * cr.top), h = Math.round(S.CAM_H * (cr.bottom - cr.top));
  items.push({ json: { spot: s.spot, break: c.break, still: c.still + '?t=' + Date.now(),
    camW: S.CAM_W, cropY: y, cropH: h, outW: Math.round(S.CAM_W * cr.zoom), outH: Math.round(h * cr.zoom) } });
}
return items.length ? items : [{ json: { spot: null, break: 'no cam', still: null } }];

// Claude takes the cropped frame as base64. A failed download or crop leaves no image, which reads as "cam unreadable".
const cams = $('Cam stills').all();
const out = [];
for (let i = 0; i < $input.all().length; i++) {
  let image_b64 = null;
  try { image_b64 = (await this.helpers.getBinaryDataBuffer(i, 'data')).toString('base64'); } catch (e) {}
  out.push({ json: { break: cams[i]?.json.break, image_b64 } });
}
return out;

const S = $('Kook settings').first().json;
const m = $('Score the morning').first().json;
const cams = $('Cam stills').all().map(i => i.json);
const counts = $('Count heads (Claude vision)').all().map((it, k) => {
  let surfers = null, visibility = 'unknown';
  const txt = (it.json.content || []).map(c => c.text || '').join(' ');
  try {
    const j = JSON.parse(txt.slice(txt.lastIndexOf('{'), txt.lastIndexOf('}') + 1));   // the JSON is the LAST line, after the list
    surfers = Number.isFinite(j.surfers) ? j.surfers : null; visibility = j.visibility || visibility;
  } catch (e) {}
  if (surfers == null) { const t = txt.match(/total[^0-9]{0,20}(\d+)/i); if (t) surfers = Number(t[1]); }   // reply cut off before the JSON
  const seed = S.SEED_CROWD && S.SEED_CROWD[cams[k]?.break];
  if (visibility === 'dark') surfers = null;   // a black frame "counts" 0, which would read as an empty lineup
  if (seed != null && surfers == null) surfers = seed;
  return { break: cams[k]?.break, spot: cams[k]?.spot, surfers, visibility };
}).filter(c => c.break && c.break !== 'no cam');
const TZ = 'Australia/Perth';
const clock = d => new Intl.DateTimeFormat('en-AU', { timeZone: TZ, hour: 'numeric', minute: '2-digit' }).format(d).replace(' ', '').toLowerCase();
const WORDS = ['Nobody', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine', 'Ten', 'Eleven', 'Twelve',
  'Thirteen', 'Fourteen', 'Fifteen', 'Sixteen', 'Seventeen', 'Eighteen', 'Nineteen', 'Twenty'];
const best = m.spots[0];
const readable = counts.filter(c => c.surfers != null);
const pick = best.cams.length && readable.length ? readable.sort((a, b) => a.surfers - b.surfers)[0] : null;
const where = pick ? pick.break : best.spot;
const out = pick ? pick.surfers : null;
const now = new Date();
// A forced run means "go now", so the session starts one drive from now rather than at the forecast's best hour.
let start = new Date(Math.max(m.forced || S.FORCE_FIRE ? 0 : new Date(best.best.at).getTime(), now.getTime() + S.TRAVEL_MIN * 60e3));
start = new Date(Math.ceil(start.getTime() / 300e3) * 300e3);
const leave = new Date(start.getTime() - S.TRAVEL_MIN * 60e3);
const end = new Date(start.getTime() + S.SESSION_MIN * 60e3);
const home = new Date(end.getTime() + S.TRAVEL_MIN * 60e3);
const callAt = S.TEST_MODE ? new Date(now.getTime() + 60e3) : end;   // ring the bakery as the drive home starts
const crowdWord = out == null ? 'Cam\'s blind' : `${WORDS[out] ?? out} out`;
const verdict = `${crowdWord}. ${best.best.windType}. ${(out ?? 0) <= 25 ? 'Worth it. Get up.' : 'Packed. Still worth it.'}`;
const lines = [
  ...counts.map(c => `${c.break}: ${c.surfers != null ? c.surfers + ' out' : c.visibility === 'dark' ? 'too dark to count' : 'cam unreadable'}`),
  ...m.spots.filter(s => !s.cams.length).map(s => `${s.spot}: no cam, ${s.best ? s.best.surfFt + 'ft ' + s.best.windType.toLowerCase() : 'no forecast'}`),
];
const smsText = `KOOK: ${verdict}\nGo ${where}! Best at ${clock(start)}.\n${best.spot} ${best.best.surfFt}ft, ${best.best.windKt}kn ${best.best.windType.toLowerCase()} (${best.source})\n\n${lines.join('\n')}`;
return [{ json: {
  verdict, where, surfers: out, spot: best.spot, forecast: best.best, counts, forced: m.forced,
  smsText,
  askText: `🏄 ${verdict}\nGo ${where} at ${clock(start)}.\n\nChase Barrels or go to work?`,
  planText: `Sorted. Sick text sent${S.CALENDAR_ID ? ', meetings moved to tomorrow' : ''}.\nLeave ${clock(leave)}. Paddle out ${clock(start)}. In till ${clock(end)}. Home ${clock(home)}.\nPie and custard tart ordered on the drive home.`,
  leaveAt: leave.toISOString(), startAt: start.toISOString(), endAt: end.toISOString(), homeAt: home.toISOString(), callAt: callAt.toISOString(),
} }];
